package com.deardiary.privateapp;
import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;
/** App-owned cover, not a replacement for Android's biometric prompt. */
final class LockScreen extends ScrollView{
 private final LinearLayout content;private final boolean dark;private final int ink,muted;private TextView hint;private Button retry;
 private int dp(float n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}
 LockScreen(Context context,boolean night,Runnable authenticate,Runnable pin,Runnable close){super(context);setFillViewport(true);setClipToPadding(false);content=new LinearLayout(context);super.addView(content,new ScrollView.LayoutParams(-1,-2));dark=night;ink=Color.parseColor(dark?"#F3E8ED":"#594553");muted=Color.parseColor(dark?"#C2ADB9":"#8B7781");content.setOrientation(LinearLayout.VERTICAL);content.setGravity(Gravity.CENTER);content.setPadding(dp(28),dp(48),dp(28),dp(36));setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{Color.parseColor(dark?"#17141D":"#F8F5F0"),Color.parseColor(dark?"#29212D":"#F2E7EC")}));
  ImageView book=new ImageView(context);book.setImageResource(com.deardiary.privateapp.R.drawable.app_icon);book.setContentDescription(null);LinearLayout.LayoutParams icon=new LinearLayout.LayoutParams(dp(94),dp(94));icon.bottomMargin=dp(18);content.addView(book,icon);
  TextView brand=label("Dear Diary",34,ink);brand.setTypeface(Typeface.create("serif",Typeface.NORMAL));content.addView(brand);TextView privateLabel=label("A little space, just for you",14,muted);LinearLayout.LayoutParams subtitle=new LinearLayout.LayoutParams(-1,-2);subtitle.topMargin=dp(8);subtitle.bottomMargin=dp(38);content.addView(privateLabel,subtitle);
  Fingerprint glyph=new Fingerprint(context,Color.parseColor(dark?"#E6AFC2":"#A97087"));LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(dp(58),dp(58));fp.bottomMargin=dp(18);content.addView(glyph,fp);TextView title=label("Welcome back",22,ink);title.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));content.addView(title);
  hint=label("Unlock with your fingerprint\nor phone screen lock",14,muted);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,-2);hp.topMargin=dp(10);hp.bottomMargin=dp(28);content.addView(hint,hp);
  retry=button("Unlock with device",true);retry.setOnClickListener(v->authenticate.run());content.addView(retry,buttonParams());Button fallback=button("Use diary PIN instead",false);fallback.setOnClickListener(v->pin.run());LinearLayout.LayoutParams fallbackParams=buttonParams();fallbackParams.topMargin=dp(10);content.addView(fallback,fallbackParams);
  TextView privacy=label("Your pages stay private until you unlock.",12,muted);LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-1,-2);pp.topMargin=dp(26);content.addView(privacy,pp);TextView exit=label("Close app",13,muted);exit.setPadding(dp(16),dp(18),dp(16),dp(12));exit.setOnClickListener(v->close.run());exit.setContentDescription("Close app");exit.setFocusable(true);content.addView(exit);
 }
 private TextView label(String s,int size,int color){TextView t=new TextView(getContext());t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER);t.setLineSpacing(dp(3),1);return t;}
 private LinearLayout.LayoutParams buttonParams(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(54));p.width=Math.min(getResources().getDisplayMetrics().widthPixels-dp(56),dp(330));p.gravity=Gravity.CENTER;return p;}
 private Button button(String text,boolean primary){Button b=new Button(getContext());b.setText(text);b.setTextSize(14);b.setAllCaps(false);b.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));b.setTextColor(primary?Color.parseColor(dark?"#39212F":"#FFFFFF"):ink);GradientDrawable bg=new GradientDrawable();bg.setCornerRadius(dp(18));bg.setColor(Color.parseColor(primary?(dark?"#E6AFC2":"#A97087"):(dark?"#302733":"#FFFAFB")));if(!primary)bg.setStroke(dp(1),Color.parseColor(dark?"#5D4857":"#DDCDD5"));b.setBackground(bg);return b;}
 void asking(){hint.setText("Confirm in Android's secure prompt");retry.setText("Unlock with device");}
 void retry(){hint.setText("Try your fingerprint again, or use\nyour phone screen lock or diary PIN.");retry.setText("Try again");}
 void reveal(){setAlpha(0f);setTranslationY(dp(8));animate().alpha(1f).translationY(0).setDuration(220).start();}
 static final class Fingerprint extends View{private final Paint p=new Paint(3);Fingerprint(Context c,int color){super(c);p.setColor(color);p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeWidth(2.7f);setContentDescription("Fingerprint unlock");}protected void onDraw(Canvas canvas){super.onDraw(canvas);canvas.save();canvas.scale(getWidth()/58f,getHeight()/58f);for(int i=0;i<4;i++){float inset=6+i*5;RectF r=new RectF(inset,inset,58-inset,58-inset+7);canvas.drawArc(r,190,160,false,p);canvas.drawArc(r,12,70,false,p);if(i<3)canvas.drawArc(r,105,58,false,p);}canvas.drawLine(29,27,29,48,p);canvas.restore();}}
}
